package com.library.exception;
import com.library.common.constant.StatusCode; import com.library.common.exception.*; import com.library.common.model.ApiResult; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.ExceptionHandler; import org.springframework.web.bind.annotation.RestControllerAdvice;
@RestControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(UnauthorizedException.class) public ApiResult<Void> unauthorized(UnauthorizedException e){return ApiResult.error(StatusCode.UNAUTHORIZED,e.getMessage());} @ExceptionHandler(BusinessException.class) public ApiResult<Void> business(BusinessException e){return ApiResult.error(StatusCode.BAD_REQUEST,e.getMessage());} @ExceptionHandler(MethodArgumentNotValidException.class) public ApiResult<Void> valid(MethodArgumentNotValidException e){return ApiResult.error(StatusCode.BAD_REQUEST,"参数校验失败");} @ExceptionHandler(Exception.class) public ApiResult<Void> other(Exception e){return ApiResult.error(StatusCode.SERVER_ERROR,"服务器内部错误");} }
